CREATE TABLE public.page_views(id bigserial PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),visitor_id text NOT NULL,session_id text NOT NULL,path text NOT NULL,source text NOT NULL DEFAULT 'Direct / None',device text NOT NULL DEFAULT 'Desktop');
GRANT ALL ON public.page_views TO service_role;
ALTER TABLE public.page_views ENABLE ROW LEVEL SECURITY;
CREATE INDEX page_views_created_idx ON public.page_views(created_at);
CREATE OR REPLACE FUNCTION public.track_view(_visitor text,_session text,_path text,_source text,_device text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(_visitor)>64 OR length(_session)>64 OR length(_path)>300 OR _path !~ '^/' THEN RETURN; END IF; IF _path ~ '^/(smart-websites|reset-password|invite|cms-media|api)' THEN RETURN; END IF; INSERT INTO public.page_views(visitor_id,session_id,path,source,device) VALUES(_visitor,_session,_path,left(coalesce(nullif(_source,''),'Direct / None'),80),CASE WHEN _device IN ('Mobile','Tablet','Laptop','Desktop') THEN _device ELSE 'Desktop' END); END $$;
GRANT EXECUTE ON FUNCTION public.track_view(text,text,text,text,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.get_stats(_days int) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE since timestamptz := date_trunc('day',now())-make_interval(days=>greatest(least(_days,366),1)-1); BEGIN IF NOT public.can_edit(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN jsonb_build_object('daily',(SELECT coalesce(jsonb_agg(jsonb_build_object('day',d::date,'visitors',coalesce(v.u,0),'views',coalesce(v.c,0)) ORDER BY d),'[]') FROM generate_series(since,date_trunc('day',now()),interval '1 day') d LEFT JOIN (SELECT date_trunc('day',created_at) dd,count(DISTINCT visitor_id) u,count(*) c FROM page_views WHERE created_at>=since GROUP BY 1) v ON v.dd=d),'visitors',(SELECT count(DISTINCT visitor_id) FROM page_views WHERE created_at>=since),'views',(SELECT count(*) FROM page_views WHERE created_at>=since),'pages',(SELECT coalesce(jsonb_agg(jsonb_build_object('k',path,'n',n)),'[]') FROM (SELECT path,count(*) n FROM page_views WHERE created_at>=since GROUP BY 1 ORDER BY 2 DESC LIMIT 25) x),'entries',(SELECT coalesce(jsonb_agg(jsonb_build_object('k',path,'n',n)),'[]') FROM (SELECT path,count(*) n FROM (SELECT DISTINCT ON(session_id) path FROM page_views WHERE created_at>=since ORDER BY session_id,created_at) s GROUP BY 1 ORDER BY 2 DESC LIMIT 25) x),'exits',(SELECT coalesce(jsonb_agg(jsonb_build_object('k',path,'n',n)),'[]') FROM (SELECT path,count(*) n FROM (SELECT DISTINCT ON(session_id) path FROM page_views WHERE created_at>=since ORDER BY session_id,created_at DESC) s GROUP BY 1 ORDER BY 2 DESC LIMIT 25) x),'sources',(SELECT coalesce(jsonb_agg(jsonb_build_object('k',source,'n',n)),'[]') FROM (SELECT source,count(DISTINCT visitor_id) n FROM page_views WHERE created_at>=since GROUP BY 1 ORDER BY 2 DESC LIMIT 25) x),'devices',(SELECT coalesce(jsonb_agg(jsonb_build_object('k',device,'n',n)),'[]') FROM (SELECT device,count(DISTINCT visitor_id) n FROM page_views WHERE created_at>=since GROUP BY 1 ORDER BY 2 DESC) x)); END $$;
CREATE OR REPLACE FUNCTION public.log_audit(_action text,_target text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ INSERT INTO public.audit_log(actor,actor_email,action,target) SELECT auth.uid(),(SELECT email FROM auth.users WHERE id=auth.uid()),left(_action,120),left(_target,300) WHERE public.can_edit(auth.uid()) AND _action IN ('Back-up teruggezet','Versie teruggezet','Alles gepubliceerd','Gebruiker uitgenodigd','Gebruiker verwijderd') $$;
CREATE OR REPLACE FUNCTION public.system_check() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN jsonb_build_object('admins',(SELECT count(*) FROM user_roles WHERE role='admin'),'bucket',EXISTS(SELECT 1 FROM storage.buckets WHERE id='cms-media' AND NOT public),'tables_without_rls',(SELECT coalesce(jsonb_agg(c.relname),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r' AND NOT c.relrowsecurity),'site_domain',(SELECT site_domain FROM site_settings WHERE id=1)); END $$;
CREATE OR REPLACE FUNCTION public.create_site_backup() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE new_id uuid; BEGIN IF NOT public.can_edit(auth.uid()) THEN RAISE EXCEPTION 'Geen rechten'; END IF; INSERT INTO site_backups(created_by,created_by_email,data) VALUES(auth.uid(),(SELECT email FROM auth.users WHERE id=auth.uid()),jsonb_build_object('page_content',coalesce((SELECT jsonb_agg(to_jsonb(c)) FROM page_content c),'[]'::jsonb),'page_seo',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM page_seo s),'[]'::jsonb),'page_settings',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM page_settings p),'[]'::jsonb))) RETURNING id INTO new_id; DELETE FROM site_backups WHERE id IN(SELECT id FROM site_backups ORDER BY created_at DESC OFFSET 3); RETURN new_id; END $$;
CREATE OR REPLACE FUNCTION public.restore_site_backup(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Geen rechten'; END IF; SELECT data INTO b FROM site_backups WHERE id=_id; IF b IS NULL THEN RAISE EXCEPTION 'Back-up niet gevonden'; END IF; DELETE FROM page_content WHERE true; DELETE FROM page_seo WHERE true; DELETE FROM page_settings WHERE true; INSERT INTO page_content SELECT * FROM jsonb_populate_recordset(NULL::public.page_content,b->'page_content'); INSERT INTO page_seo SELECT * FROM jsonb_populate_recordset(NULL::public.page_seo,b->'page_seo'); INSERT INTO page_settings SELECT * FROM jsonb_populate_recordset(NULL::public.page_settings,b->'page_settings'); END $$;
CREATE OR REPLACE FUNCTION public.rename_custom_page(_old text,_new text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_perm(auth.uid(),'pages') THEN RAISE EXCEPTION 'Geen rechten'; END IF; IF split_part(_old,'/',2)<>split_part(_new,'/',2) THEN RAISE EXCEPTION 'Taal mag niet wijzigen'; END IF; IF NOT EXISTS(SELECT 1 FROM custom_pages WHERE path=_old) THEN RAISE EXCEPTION 'Alleen zelf aangemaakte pagina''s kunnen een nieuwe URL krijgen'; END IF; IF EXISTS(SELECT 1 FROM custom_pages WHERE path=_new) THEN RAISE EXCEPTION 'Deze URL bestaat al'; END IF; UPDATE custom_pages SET path=_new WHERE path=_old; UPDATE custom_pages SET pair_path=_new WHERE pair_path=_old; UPDATE page_content SET path=_new WHERE path=_old; UPDATE page_settings SET path=_new WHERE path=_old; UPDATE page_settings SET parent_path=_new WHERE parent_path=_old; UPDATE page_seo SET path=_new WHERE path=_old; END $$;
CREATE OR REPLACE FUNCTION public.restore_page_revision(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.page_revisions; BEGIN IF NOT public.can_edit(auth.uid()) THEN RAISE EXCEPTION 'Geen rechten'; END IF; SELECT * INTO r FROM page_revisions WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Versie niet gevonden'; END IF; INSERT INTO page_content(path,state,data,layout,updated_by,updated_at) VALUES(r.path,'draft',r.data,r.layout,auth.uid(),now()),(r.path,'published',r.data,r.layout,auth.uid(),now()) ON CONFLICT(path,state) DO UPDATE SET data=EXCLUDED.data,layout=EXCLUDED.layout,updated_by=EXCLUDED.updated_by,updated_at=now(); END $$;
CREATE OR REPLACE FUNCTION public.guard_page_layout() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.state='draft' AND auth.uid() IS NOT NULL AND NEW.layout IS DISTINCT FROM(CASE WHEN TG_OP='UPDATE' THEN OLD.layout ELSE NULL END) AND NOT public.has_perm(auth.uid(),'blocks') THEN RAISE EXCEPTION 'Je hebt geen rechten om blokken te wijzigen.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_page_layout BEFORE INSERT OR UPDATE ON public.page_content FOR EACH ROW EXECUTE FUNCTION public.guard_page_layout();
CREATE OR REPLACE FUNCTION public.guard_page_structure() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.has_perm(auth.uid(),'pages') AND ((TG_OP='INSERT' AND (NEW.sort_order IS NOT NULL OR NEW.parent_path IS NOT NULL OR NEW.deleted)) OR (TG_OP='UPDATE' AND (NEW.sort_order IS DISTINCT FROM OLD.sort_order OR NEW.parent_path IS DISTINCT FROM OLD.parent_path OR NEW.deleted IS DISTINCT FROM OLD.deleted))) THEN RAISE EXCEPTION 'Je hebt geen rechten om pagina''s te verschuiven of te verwijderen.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_page_structure BEFORE INSERT OR UPDATE ON public.page_settings FOR EACH ROW EXECUTE FUNCTION public.guard_page_structure();
CREATE OR REPLACE FUNCTION public.record_page_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.state='published' THEN INSERT INTO page_revisions(path,data,layout,created_by) VALUES(NEW.path,NEW.data,NEW.layout,NEW.updated_by); DELETE FROM page_revisions WHERE path=NEW.path AND id NOT IN(SELECT id FROM page_revisions WHERE path=NEW.path ORDER BY created_at DESC LIMIT 20); END IF; RETURN NEW; END $$;
CREATE TRIGGER page_content_revision AFTER INSERT OR UPDATE ON public.page_content FOR EACH ROW EXECUTE FUNCTION public.record_page_revision();
CREATE OR REPLACE FUNCTION public.write_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE act text; tgt text; r record; BEGIN r:=CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; IF TG_TABLE_NAME='page_content' THEN IF NEW.state<>'published' THEN RETURN NEW; END IF; act:='Pagina gepubliceerd';tgt:=NEW.path; ELSIF TG_TABLE_NAME='custom_pages' THEN act:=CASE TG_OP WHEN 'INSERT' THEN 'Pagina aangemaakt' WHEN 'DELETE' THEN 'Pagina verwijderd' ELSE 'Pagina-adres gewijzigd' END;tgt:=r.path; ELSIF TG_TABLE_NAME='page_settings' THEN IF TG_OP='UPDATE' AND NEW.deleted AND NOT OLD.deleted THEN act:='Pagina verwijderd';ELSE RETURN r;END IF;tgt:=NEW.path; ELSIF TG_TABLE_NAME='user_roles' THEN act:=CASE TG_OP WHEN 'INSERT' THEN 'Rol toegekend: '||NEW.role WHEN 'DELETE' THEN 'Rol ingetrokken: '||OLD.role ELSE 'Rol gewijzigd: '||NEW.role END;SELECT email INTO tgt FROM auth.users WHERE id=r.user_id; ELSIF TG_TABLE_NAME='media' THEN IF TG_OP<>'DELETE' THEN RETURN r;END IF;act:='Bestand verwijderd';tgt:=OLD.name; ELSIF TG_TABLE_NAME='site_settings' THEN act:='Instellingen gewijzigd'; ELSIF TG_TABLE_NAME='cms_roles' THEN act:=CASE TG_OP WHEN 'DELETE' THEN 'Rolprofiel verwijderd' ELSE 'Rolprofiel gewijzigd' END;tgt:=r.name; ELSIF TG_TABLE_NAME='site_backups' THEN act:='Back-up gemaakt'; END IF; INSERT INTO audit_log(actor,actor_email,action,target) VALUES(auth.uid(),(SELECT email FROM auth.users WHERE id=auth.uid()),act,tgt);RETURN r;END $$;
CREATE TRIGGER audit_page_content AFTER INSERT OR UPDATE ON public.page_content FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE TRIGGER audit_custom_pages AFTER INSERT OR UPDATE OR DELETE ON public.custom_pages FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE TRIGGER audit_page_settings AFTER UPDATE ON public.page_settings FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE TRIGGER audit_user_roles AFTER INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE TRIGGER audit_media AFTER DELETE ON public.media FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE TRIGGER audit_site_settings AFTER UPDATE ON public.site_settings FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE TRIGGER audit_cms_roles AFTER INSERT OR UPDATE OR DELETE ON public.cms_roles FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE TRIGGER audit_site_backups AFTER INSERT ON public.site_backups FOR EACH ROW EXECUTE FUNCTION public.write_audit();
REVOKE EXECUTE ON FUNCTION public.get_stats(int),public.log_audit(text,text),public.system_check(),public.create_site_backup(),public.restore_site_backup(uuid),public.rename_custom_page(text,text),public.restore_page_revision(uuid) FROM public,anon;
GRANT EXECUTE ON FUNCTION public.get_stats(int),public.log_audit(text,text),public.system_check(),public.create_site_backup(),public.restore_site_backup(uuid),public.rename_custom_page(text,text),public.restore_page_revision(uuid) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.guard_page_layout(),public.guard_page_structure(),public.record_page_revision(),public.write_audit() FROM public,anon,authenticated;